"""configloader — implement parse_config and get per README.md."""


def _coerce(value):
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        return value[1:-1]
    low = value.lower()
    if low == "true":
        return True
    if low == "false":
        return False
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    return value


def parse_config(text):
    config = {}
    section = ""
    config[section] = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        if "=" not in line:
            continue
        key, _, value = line.partition("=")
        config[section][key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    if "." in dotted:
        section, key = dotted.split(".", 1)
    else:
        section, key = "", dotted
    return config.get(section, {}).get(key, default)

